svg.metadata:
flowchart TB
  A["init / pre-send check"]
  B{"Usable session exists?"}
  C["Wait for the pending handshake<br/>Use its success or failure result"]
  D["Generate local SM2 keys; POST the public key only"]
  E["Server validates and registers the key; returns ID, key, budget and TTL"]
  F["Validate response; check cancellation and expiry"]
  G["Return success; ready() is true"]
  H["Return failure; publish no partial session"]
  A --> B
  B -->|"yes"| G
  B -->|"no; handshake pending"| C
  B -->|"no; start handshake"| D
  D --> E
  E --> F
  E -->|"registration rejected / quota full"| H
  F -->|"all checks pass"| G
  D -->|"key / network failure"| H
  F -->|"invalid / cancelled / timed out"| H
  classDef default fill:#edf3ff,stroke:#476aab,color:#172b4d,stroke-width:1.5px;
  classDef good fill:#e9f6ef,stroke:#28734e,color:#17452f,stroke-width:1.5px;
  classDef stop fill:#fff0f0,stroke:#af4040,color:#742b2b,stroke-width:1.5px;
  classDef pending fill:#fff6df,stroke:#a07827,color:#654b18,stroke-width:1.5px;
  class G good;
  class H stop;
  class C pending;
